import{t as e}from"./auth.DU1tc4gE.js";e.isAuthenticated()&&(window.location.href=`/`);var t=document.getElementById(`registro-form`),n=document.getElementById(`reg-submit-btn`),r=document.getElementById(`reg-error-alert`),i=document.getElementById(`reg-success-alert`);t&&t.addEventListener(`submit`,async t=>{t.preventDefault(),r.style.display=`none`,i.style.display=`none`;let a=document.getElementById(`nombre`).value.trim(),o=document.getElementById(`email`).value.trim(),s=document.getElementById(`password`).value,c=document.getElementById(`confirmPassword`).value,l=document.getElementById(`telefono`).value.trim(),u=document.getElementById(`direccion`).value.trim();if(!a||!o||!s){r.textContent=`Por favor completa los campos obligatorios (*).`,r.style.display=`block`;return}if(s.length<6){r.textContent=`La contraseña debe contener al menos 6 caracteres.`,r.style.display=`block`;return}if(s!==c){r.textContent=`Las contraseñas no coinciden. Verifícalas.`,r.style.display=`block`;return}n.disabled=!0,n.innerHTML=`<span>Creando cuenta...</span>`;try{i.textContent=`¡Cuenta creada exitosamente! Bienvenido, ${(await e.registro({nombre:a,email:o,password:s,telefono:l,direccion:u})).usuario.nombre}.`,i.style.display=`block`,window.showToast&&window.showToast(`¡Registro exitoso! Iniciando sesión...`,`success`),setTimeout(()=>{window.location.href=`/catalogo`},800)}catch(e){r.textContent=e.message||`Error al registrar la cuenta. Intenta de nuevo.`,r.style.display=`block`,n.disabled=!1,n.innerHTML=`<span>Registrarme y Comenzar</span>`}});